using System;using System.IO;using UnityEngine;using SkyIsland;
public static class AdventureReview {
 public static void Validate(){int n=0;Action<bool,string> check=(ok,name)=>{if(!ok)throw new Exception("ADVENTURE FAIL "+name);n++;};
  var chest=new SpringChestState();SpringChestRules.Schedule(chest,100,0);check(chest.nextAt==280,"minimum3minutes");check(!SpringChestRules.Spawn(chest,279,0,1),"no early spawn");SpringChestRules.Schedule(chest,100,1);check(chest.nextAt==580,"maximum8minutes");
  float[] rolls={0,.5f,.75f,.88f,.96f,.99f};for(int tier=0;tier<6;tier++){check(SpringChestRules.Tier(rolls[tier])==tier,"six tier weight boundary "+tier);var s=new SpringChestState{tier=tier,seed=155,pending=true};SpringChestRules.Puzzle(s);check(s.board.Length==36&&s.moves==18&&SpringChestRules.Goal(s)==24+tier*5,"road game puzzle "+tier);check(SpringChestRules.Clear(s,0)&&s.moves==17,"connected clear "+tier);check(SpringChestRules.Valid(JsonUtility.FromJson<SpringChestState>(JsonUtility.ToJson(s))),"puzzle save reload "+tier);SpringChestRules.Puzzle(s);for(int turn=0;turn<18&&s.score<SpringChestRules.Goal(s);turn++){int best=0;for(int i=1;i<36;i++)if(SpringChestRules.Group(s.board,i).Count>SpringChestRules.Group(s.board,best).Count)best=i;SpringChestRules.Clear(s,best);}check(s.score>=SpringChestRules.Goal(s),"puzzle has winning deterministic path "+tier);}
  var island=new HexIsland();var state=new SurvivalState();var inv=new SurvivalInventory(island,state);chest=new SpringChestState{pending=true,tier=5,score=0};check(SpringChestRules.Claim(chest,island,inv,0,0,()=>true)=="locked","reward requires win");chest.score=100;check(SpringChestRules.Claim(chest,island,inv,0,0,()=>false)=="save-failed"&&chest.pending&&island.Wood==0&&state.food==0,"claim failure rolls back");island.Wood=1000000;check(SpringChestRules.Claim(chest,island,inv,0,0,()=>true)=="full"&&chest.pending,"inventory full retains chest");island.Wood=0;check(SpringChestRules.Claim(chest,island,inv,100,1,()=>true)=="complete"&&island.Wood==640&&island.Stone==320&&state.food==64&&chest.nextAt==580,"claim once all rewards and next timer");check(SpringChestRules.Claim(chest,island,inv,100,0,()=>true)=="locked"&&island.Wood==640,"repeat claim denied");
  check(!SpringChestRules.Valid(new SpringChestState{pending=true,board=new int[2]}),"invalid board rejected");
  var low=AirshipRules.Clamp(new Vector3(0,-50,0),island.Cells);check(low.y==3,"flight minimum height");var high=AirshipRules.Clamp(new Vector3(1000,100,1000),island.Cells);check(high.y==16,"flight ceiling");float distance=float.MaxValue;foreach(var c in island.Cells){var delta=high-c.World;delta.y=0;distance=Mathf.Min(distance,delta.magnitude);}check(distance<=AirshipRules.Range+Hex.Radius+.001f,"flight range clamped near owned island");island.Cells.Add(new Hex(80,0));var far=new Hex(80,0).World+Vector3.up*5;check(Vector3.Distance(AirshipRules.Clamp(far,island.Cells),far)<.001f,"range follows expanded island");
  var nature=new NatureWorldState{initialized=true};var tree=new NatureSpawn{kind=0,health=2,cell=new Hex(-1,0)};NatureRules.Add(nature,tree);island.Wood=0;NatureRules.Harvest(nature,tree,inv,island,15,()=>true);check(island.Wood==150&&tree.harvestedSeconds==15,"legacy health does not shorten 30s");var restored=JsonUtility.FromJson<NatureWorldState>(JsonUtility.ToJson(nature));check(NatureRules.Valid(restored)&&restored.nodes[0].delivered==150,"partial harvest persists");NatureRules.Harvest(restored,restored.nodes[0],inv,island,15,()=>true);check(island.Wood==300&&restored.nodes.Count==0,"resume only remaining reward");check(NatureRules.Harvest(nature,tree,inv,island,float.NaN,()=>true)=="missing","nonfinite time rejected");
  Directory.CreateDirectory("../evidence/unity");File.WriteAllText("../evidence/unity/adventure-tests.txt","PASS "+n+" harvest/chest/match/range/save assertions; UTC "+DateTime.UtcNow.ToString("o")+"\nPure Unity rules exercised; browser interaction/mobile performance still pending.");Debug.Log("SKY_ADVENTURE_TESTS_PASS "+n);
 }
}
